pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 callCount) public {
        vm.assume(callCount >= 1 && callCount <= 10);
        bool firstOk = true;
        bool secondOk = true;
        vm.prank(c.owner());
        try c.sudicideAnyone() {} catch { firstOk = false; }
        vm.prank(c.owner());
        try c.sudicideAnyone() {} catch { secondOk = false; }
        assertTrue(!(firstOk && secondOk));
    }
}
// The owner() getter is inherited from sGuardPlus but __owner is private; however, the provided contract C extends sGuardPlus which has no public owner getter. The modifier __onlyOwner uses the private __owner. Since __owner is private, there is no getter, and c.owner() would fail to compile. To access the owner, we deploy via setUp and use the original msg.sender as the known owner. We adjust accordingly.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;
    function setUp() public {
        owner = address(this);
        c = new C();
    }
    function testFuzz_property(uint8 callCount) public {
        vm.assume(callCount >= 1 && callCount <= 5);
        bool firstOk = true;
        bool secondOk = true;
        vm.prank(owner);
        try c.sudicideAnyone() {} catch { firstOk = false; }
        if (firstOk) {
            vm.prank(owner);
            try c.sudicideAnyone() {} catch { secondOk = false; }
            assertTrue(!secondOk);
        } else {
            assertTrue(false);
        }
    }
}

