import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint8 callTwice) public {
        vm.assume(owner != address(0));
        vm.prank(owner);
        vm.deal(owner, 0);
        // The owner calls sudicideAnyone; if it self-destructs, a second call will revert.
        c.sudicideAnyone();
        bool secondOk;
        try c.sudicideAnyone() { secondOk = true; } catch { secondOk = false; }
        // The reference self-destructs and the second call reverts (secondOk == false).
        // The mutant stays alive and the second call succeeds (secondOk == true).
        assertTrue(secondOk == false);
    }
}

