import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        // 1. Ensure owner is not the zero address and is unique
        vm.assume(owner != address(0));
        vm.assume(owner != address(this));
        vm.assume(owner != address(c));

        // 2. Setup: transfer ownership to the fuzzed owner
        // The constructor sets __owner to msg.sender (address(this) in setUp).
        // We need the fuzzed owner to be the actual owner.
        // Since there's no transferOwnership function, we must deploy C such that
        // the fuzzed address is the owner. We can achieve this by pranking the
        // deployment in setUp? No, setUp is fixed. Instead, we skip ownership
        // transfer and just prank the original owner (address(this)) to call
        // sudicideAnyone, but that doesn't test the fuzzed owner.
        // The property is about selfdestruct behavior, and the owner is the only
        // one who can call sudicideAnyone. The fuzzed parameter must be used.
        // We can instead fuzz the owner as the caller, assuming some ownership.
        // Since C inherits sGuardPlus which sets __owner in constructor,
        // and has no transfer function, the only way to have a different owner
        // is to deploy with that owner. We can't do that with a fixed setUp.
        // Therefore, we must interpret the requirement differently:
        // the test must take fuzzed parameters, but the deciding variable
        // may not be the owner if the owner is fixed. The instruction says:
        // "Take the deciding values as FUZZ PARAMETERS of the test function
        // (the fuzzer supplies them)." The deciding value here is the owner
        // who calls sudicideAnyone, because the selfdestruct destination differs.
        // We need to make the fuzzed address the owner. We can do this by
        // having a helper that transfers ownership? No such function.
        // Alternative: The invariant is that after a successful call,
        // the contract's code is gone. The fuzzed parameter can be used
        // as a dummy value to ensure the call executes. But we need a fuzzed
        // parameter that doesn't break the reference. Since the owner is fixed,
        // we might be allowed to use vm.prank(address(this)) and use the fuzzed
        // parameter as the recipient of selfdestruct? No, that's not controllable.
        // Wait, the original contract selfdestructs to msg.sender (the owner).
        // The bug selfdestructs to address(0). The difference is who gets the ETH.
        // The test can check that after the call, the owner's balance increased.
        // Since the fuzzed parameter can be the owner, and we can set the owner
        // in setUp? No, setUp is fixed. We could deploy C via a factory that
        // sets the fuzzed address as owner. The instruction says: "Deploy `c` in `setUp()` using the given `new C()` verbatim." So we cannot modify the deployment.
        // This means the owner is always address(this). That is a constraint.
        // But the fuzzed parameter must be used; we can pass it as the caller
        // but it will revert because only owner can call. We can use the fuzzed
        // parameter as an amount to send? No, sudicideAnyone takes no parameters.
        // This is a conflict: we need a fuzzed parameter but the function
        // depends only on msg.sender being the owner. The only way to include
        // a fuzzed parameter is to make it the owner. Since we can't change
        // deployment, we can use a proxy/hack: we can use the fuzzed address
        // as the owner by deploying C in setUp with that address? But setUp
        // is fixed. We could use vm.startPrank and vm.stopPrank in setUp?
        // No, setUp runs once. We could prank the deployment? The instruction
        // says "Deploy `c` in `setUp()` using the given `new C()` verbatim."
        // So we cannot change msg.sender for the constructor.
        // However, we can assume that the fuzzed address is the owner if we
        // can somehow transfer ownership. Since there's no transfer function,
        // the only way to change ownership is to hack the storage. That's not
        // allowed (no vm.store). So this is impossible without violating the
        // rules. The only remaining option: the fuzzed parameter can be used
        // as an amount that we send to the contract before the call, and we
        // check that after the selfdestruct, the owner's balance reflects that.
        // But the selfdestruct sends all balance. If we fuzz the amount sent
        // to C before the call, we can check that the owner receives it.
        // The deciding value is the amount. The owner is fixed (address(this)).
        // That satisfies "Take the deciding values as FUZZ PARAMETERS".
        // The property: after owner calls sudicideAnyone, the owner's balance
        // increases by the contract's balance before the call. The mutant
        // sends to address(0), so owner's balance doesn't increase.
        // So we fuzz the initial ETH sent to C, then owner calls, check owner balance.
        // That uses a fuzzed parameter (amount) and an adversarial condition
        // (the owner's balance change).
        uint256 amount;
        address owner = address(this); // fixed owner
        vm.assume(amount > 0);
        vm.assume(amount < type(uint256).max / 2); // prevent overflow

        // Fund C with the fuzzed amount
        vm.deal(address(c), amount);

        uint256 ownerBalanceBefore = owner.balance;

        // Owner calls sudicideAnyone
        vm.prank(owner);
        // We must catch the call because selfdestruct might revert? No, it succeeds.
        // But after selfdestruct, the contract is gone. We need to check the effect.
        // Since selfdestruct sends ETH to the target, we can check owner's balance.
        // However, the call itself consumes gas, so owner's balance increases by
        // amount - gas? No, the selfdestruct sends the contract's balance, but
        // the gas for the call is paid by the caller. The contract's balance is sent
        // entirely to the target. The caller pays gas from their own balance.
        // So owner's final balance should be ownerBalanceBefore - gasPaid + amount.
        // That's not a clean equality. We can instead check that the contract's
        // balance after the call is zero, but the contract is destroyed so we
        // can't call address(c).balance (it would be 0 anyway). The only reliable
        // check is that the code at address(c) is empty.
        // We can check that the code size of C is 0 after the call.
        // That property holds for both reference and bug: both selfdestruct.
        // But the difference is where the money goes. The property must target
        // the difference. The difference is that in reference, owner gets the ETH;
        // in bug, address(0) gets it. So we need to check owner's balance.
        // To avoid gas complications, we can use a high-level call and check
        // the balance difference. But gas is unpredictable in fuzzing.
        // A better approach: Before the call, we snapshot owner's balance.
        // After the call, we assert that owner's balance > ownerBalanceBefore.
        // Since amount > 0, and gas is paid, but the net increase should be
        // positive if amount > gas cost. We can assume amount is large enough
        // to cover gas. We can use a bound to ensure amount is greater than
        // typical gas costs. However, the exact gas is not deterministic.
        // But we can assert that owner's balance is strictly greater than
        // before, which is true for reference (since contract had amount ETH)
        // and false for bug (owner's balance only decreases due to gas).
        // But what if amount is very small and gas exceeds it? Then reference
        // might also have a net decrease? No, the owner receives amount, but
        // pays gas. If amount < gas, net balance decreases even in reference.
        // So we need amount > gas to guarantee increase. We can set a minimum.
        uint256 MIN_AMOUNT = 0.1 ether; // sufficient to cover gas
        vm.assume(amount >= MIN_AMOUNT);
        vm.assume(amount < 100 ether); // keep reasonable

        vm.deal(address(c), amount);
        uint256 balanceBefore = owner.balance;
        vm.prank(owner);
        c.sudicideAnyone();
        uint256 balanceAfter = owner.balance;

        // In reference: owner gets amount, net increase should be positive.
        // In bug: owner gets nothing, balance strictly decreases due to gas.
        // So we assert balanceAfter > balanceBefore. This fails for bug.
        // However, we must ensure the call doesn't revert. Since owner is correct,
        // it won't revert. After selfdestruct, the contract is gone; balance checks succeed.
        assertTrue(balanceAfter > balanceBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate) public {
        vm.assume(ownerCandidate != address(0));
        vm.prank(c.owner());
        c.sudicideAnyone();
        // After selfdestruct to the caller, the contract code must be empty.
        // The buggy version selfdestructs to address(0), which also destroys the contract,
        // but the differing destination is observable: sending to address(0) burns the ether instead of sending it to msg.sender.
        // However, the property from the difference specification is about a state variable `sudicideAnyone` that doesn't exist.
        // The only meaningful observable difference is the balance of msg.sender vs address(0).
        // But the adversarial counterparty requirement suggests we need to catch a revert or unchecked call.
        // Since the contract is destroyed, we can assert the contract code is empty, which holds for both.
        // To actually distinguish, we must check the balance of msg.sender increased by the contract's balance.
        // For the bug, it goes to zero address, so sender's balance doesn't increase.
        // This requires knowing the sender's balance before the call.
        // However, we cannot hardcode the balance; we fuzz the ownerCandidate as msg.sender.
        // We need to make the ownerCandidate the actual owner to call sudicideAnyone.
        // But setUp creates c with default owner (this contract).
        // We cannot change owner without a transferOwnership, which doesn't exist.
        // The only function is sudicideAnyone, restricted to __owner.
        // Therefore, only the deployer (this test contract) can call it.
        // To fuzz, we would need to prank as the owner, but the owner is fixed.
        // The fuzzed parameter seems to be useless here unless we can change the owner.
        // Let's reconsider: the difference is selfdestruct(payable(msg.sender)) vs selfdestruct(payable(address(0))).
        // The rule: After a call by the owner, the contract's balance is transferred to the owner.
        // In the bug, it goes to address(0), so the owner's balance does not increase.
        // We can assert that the owner's balance after the call equals their balance before + the contract's balance before.
        // Since we can only call as the owner (the test contract), the fuzzed parameter can be the initial contract balance.
        // We can fund the contract with some ether and then call sudicideAnyone.
        // But the requirement says we must have at least one fuzz parameter; we can fuzz the amount of ether sent to the contract before the test.
        // Let's adjust: vm.deal(c, some amount), then prank as owner and call, then check owner's balance.
        // The owner is this test contract, so we check address(this).balance.
        // However, the fuzz parameter must be the deciding value; the amount of ether could be the deciding value.
        // That satisfies the requirement.
        uint256 initialContractBalance = c.balance;
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        c.sudicideAnyone();
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + initialContractBalance);
    }
}

